ALTER TABLE users ADD COLUMN school_id bigint REFERENCES schools;
UPDATE users SET school_id=(SELECT id FROM schools WHERE code='SET' LIMIT 1) WHERE role_id=(SELECT id FROM roles WHERE name='Dean – SET');
CREATE TABLE exception_policies(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, regulation_id bigint NOT NULL REFERENCES regulations, kind text NOT NULL, authority text NOT NULL REFERENCES roles(name), active boolean NOT NULL DEFAULT false, UNIQUE(regulation_id,kind));
CREATE TABLE eligibility_snapshots(student_id bigint NOT NULL REFERENCES students, academic_year_id bigint NOT NULL REFERENCES academic_years, revision bigint NOT NULL, evaluated_at timestamptz NOT NULL DEFAULT now(), eligible_courses integer NOT NULL, floating_courses integer NOT NULL, prerequisite_blocks jsonb NOT NULL, summary text NOT NULL, PRIMARY KEY(student_id,academic_year_id));
CREATE INDEX snapshot_revision_idx ON eligibility_snapshots(academic_year_id,revision);
